DROP VIEW IF EXISTS connector."v_acmecustomer"
;;
CREATE VIEW connector."v_acmecustomer" WITH (security_invoker = true) AS WITH unified AS (
SELECT 0::int AS _ord, 't_acme_desk_erp'::text AS _src, "code"::text AS "code", "name"::text AS "name", "city"::text AS "city", "segment"::text AS "segment", "credit_limit"::text AS "credit_limit", NULL::text AS "email" FROM connector."t_acme_desk_erp" WHERE "code" IS NOT NULL
UNION ALL
SELECT 1::int AS _ord, 't_acme_desk_crm'::text AS _src, "customer"::text AS "code", "company"::text AS "name", "town"::text AS "city", NULL::text AS "segment", NULL::text AS "credit_limit", "email"::text AS "email" FROM connector."t_acme_desk_crm" WHERE "customer" IS NOT NULL
) SELECT "code", (array_agg("name" ORDER BY _ord, "name") FILTER (WHERE "name" IS NOT NULL))[1] AS "name", (array_agg("city" ORDER BY _ord, "city") FILTER (WHERE "city" IS NOT NULL))[1] AS "city", (array_agg("segment" ORDER BY _ord, "segment") FILTER (WHERE "segment" IS NOT NULL))[1] AS "segment", (array_agg("credit_limit" ORDER BY _ord, "credit_limit") FILTER (WHERE "credit_limit" IS NOT NULL))[1] AS "credit_limit", (array_agg("email" ORDER BY _ord, "email") FILTER (WHERE "email" IS NOT NULL))[1] AS "email", (1::text || '|' || octet_length("code"::text)::text || ':' || "code"::text) AS "_canonical_key", jsonb_strip_nulls(jsonb_build_object('name', CASE WHEN count(DISTINCT "name") > 1 THEN jsonb_agg(jsonb_build_object('src', _src, 'value', "name") ORDER BY _ord, "name") FILTER (WHERE "name" IS NOT NULL) END, 'city', CASE WHEN count(DISTINCT "city") > 1 THEN jsonb_agg(jsonb_build_object('src', _src, 'value', "city") ORDER BY _ord, "city") FILTER (WHERE "city" IS NOT NULL) END, 'segment', CASE WHEN count(DISTINCT "segment") > 1 THEN jsonb_agg(jsonb_build_object('src', _src, 'value', "segment") ORDER BY _ord, "segment") FILTER (WHERE "segment" IS NOT NULL) END, 'credit_limit', CASE WHEN count(DISTINCT "credit_limit") > 1 THEN jsonb_agg(jsonb_build_object('src', _src, 'value', "credit_limit") ORDER BY _ord, "credit_limit") FILTER (WHERE "credit_limit" IS NOT NULL) END, 'email', CASE WHEN count(DISTINCT "email") > 1 THEN jsonb_agg(jsonb_build_object('src', _src, 'value', "email") ORDER BY _ord, "email") FILTER (WHERE "email" IS NOT NULL) END)) AS "_conflicts" FROM unified GROUP BY "code"
;;
GRANT SELECT ON connector."v_acmecustomer" TO lumnik_app
;;
DO $lumnik_view$ BEGIN GRANT SELECT ON connector."v_acmecustomer" TO lumnik_readonly; EXCEPTION WHEN OTHERS THEN NULL; END $lumnik_view$